// Brand images of the owner (Skoomaholic Dev), embedded so the Worker needs no
// asset storage. Generated from the owner's logo: the full mark for page
// headers and the 'S' alone for the favicon and the home-screen icon.
const LOGO_WEBP='';
const FAVICON_PNG='';
const TOUCH_PNG='';
const bytes=text=>Uint8Array.from(atob(text),c=>c.charCodeAt(0));
const FILES={
  '/brand/logo.webp':[LOGO_WEBP,'image/webp'],
  '/favicon.ico':[FAVICON_PNG,'image/png'],
  '/favicon.png':[FAVICON_PNG,'image/png'],
  '/apple-touch-icon.png':[TOUCH_PNG,'image/png']
};
export const BRAND_NAME='Skoomaholic Dev';
export const LOGO_WIDTH=360,LOGO_HEIGHT=270;
// Tags for <head>: the 'S' as the tab icon.
export const BRAND_HEAD='<link rel="icon" type="image/png" href="/favicon.png">'+
  '<link rel="apple-touch-icon" href="/apple-touch-icon.png">';
// The full logo for the top of a page.
export const BRAND_LOGO='<img class="brand" src="/brand/logo.webp" alt="'+BRAND_NAME+
  '" width="180" height="135" style="display:block;margin:0 auto 12px;max-width:45%;height:auto">';
export function brandAsset(request){
  const file=FILES[new URL(request.url).pathname];
  if(!file||(request.method!=='GET'&&request.method!=='HEAD'))return null;
  return new Response(request.method==='HEAD'?null:bytes(file[0]),{headers:{
    'content-type':file[1],'cache-control':'public, max-age=86400',
    'x-content-type-options':'nosniff'}});
}
